import { motion } from "framer-motion";
import { Lightbulb, Clock, Package } from "lucide-react";
import { useState } from "react";

function Hero() {
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  const fadeUp = {
    hidden: { opacity: 0, y: 30 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
      },
    },
  };

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "#f8f9fa",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Navigation */}
      <nav
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "20px 60px",
          background: "#fff",
          borderBottom: "1px solid #e9ecef",
          position: "sticky",
          top: 0,
          zIndex: 100,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <div
            style={{
              width: "32px",
              height: "32px",
              background: "#000",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "4px",
            }}
          >
            <span style={{ color: "#fff", fontSize: "20px", fontWeight: "bold" }}>A</span>
          </div>
          <span style={{ fontSize: "24px", fontWeight: "700", color: "#000" }}>ASSEMBLE</span>
        </div>

        <div style={{ display: "flex", gap: "40px", alignItems: "center" }}>
          <a href="#" style={{ color: "#495057", textDecoration: "none", fontSize: "15px", fontWeight: "500", borderBottom: "2px solid #ff6b35", paddingBottom: "8px" }}>
            My Project
          </a>
          <a href="#" style={{ color: "#868e96", textDecoration: "none", fontSize: "15px", fontWeight: "500" }}>
            Resources
          </a>
          <a href="#" style={{ color: "#868e96", textDecoration: "none", fontSize: "15px", fontWeight: "500" }}>
            Library
          </a>
          <a href="#" style={{ color: "#868e96", textDecoration: "none", fontSize: "15px", fontWeight: "500" }}>
            About Us
          </a>
        </div>

        <div style={{ display: "flex", gap: "20px", alignItems: "center" }}>
          <button style={{ background: "none", border: "none", cursor: "pointer", fontSize: "18px", color: "#868e96", padding: "8px" }}>
            🔔
          </button>
          <button style={{ background: "none", border: "none", cursor: "pointer", fontSize: "18px", color: "#868e96", padding: "8px" }}>
            🔔
          </button>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              style={{
                background: "none",
                border: "none",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "15px",
                color: "#495057",
                fontWeight: "500",
                padding: "8px 12px",
                borderRadius: "6px",
                transition: "background 0.2s",
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#f8f9fa"}
              onMouseLeave={(e) => e.currentTarget.style.background = "none"}
            >
              <span style={{ fontSize: "20px" }}>👤</span>
              My Profile
            </button>
            {showProfileMenu && (
              <div style={{
                position: "absolute",
                top: "100%",
                right: 0,
                marginTop: "8px",
                background: "#fff",
                border: "1px solid #e9ecef",
                borderRadius: "6px",
                padding: "8px",
                boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
                minWidth: "140px"
              }}>
                <button style={{
                  width: "100%",
                  padding: "8px 12px",
                  background: "none",
                  border: "none",
                  textAlign: "left",
                  cursor: "pointer",
                  fontSize: "14px",
                  color: "#495057",
                  borderRadius: "4px"
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = "#f8f9fa"}
                onMouseLeave={(e) => e.currentTarget.style.background = "none"}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <motion.div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "80px",
          maxWidth: "1400px",
          margin: "0 auto",
          padding: "80px 60px",
          alignItems: "center",
        }}
        initial="hidden"
        animate="visible"
        variants={staggerContainer}
      >
        {/* Left Content */}
        <motion.div variants={fadeUp}>
          <h1
            style={{
              fontSize: "56px",
              fontWeight: "700",
              color: "#212529",
              marginBottom: "24px",
              lineHeight: "1.2",
              letterSpacing: "-0.02em",
            }}
          >
            AI-driven Interior
            <br />
            Proposals in Minutes
          </h1>

          <p
            style={{
              fontSize: "18px",
              color: "#495057",
              marginBottom: "40px",
              lineHeight: "1.7",
            }}
          >
            ASSEMBLE은 사용자의 요청사항에 맞게
            <br />
            AI 기반 인테리어를 추천합니다
          </p>

          <div style={{ display: "flex", gap: "16px" }}>
            <motion.button
              style={{
                padding: "14px 32px",
                fontSize: "15px",
                fontWeight: "600",
                border: "none",
                borderRadius: "6px",
                background: "#ff6b35",
                color: "#fff",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
              whileHover={{ background: "#ff5722" }}
              whileTap={{ scale: 0.98 }}
            >
              Get Started
            </motion.button>

            <motion.button
              style={{
                padding: "14px 32px",
                fontSize: "15px",
                fontWeight: "600",
                border: "1px solid #dee2e6",
                borderRadius: "6px",
                background: "#fff",
                color: "#495057",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
              whileHover={{ background: "#f8f9fa" }}
              whileTap={{ scale: 0.98 }}
            >
              Learn More
            </motion.button>
          </div>
        </motion.div>

        {/* Right Image */}
        <motion.div
          variants={fadeUp}
          style={{
            borderRadius: "12px",
            overflow: "hidden",
            boxShadow: "0 20px 60px rgba(0, 0, 0, 0.1)",
          }}
        >
          <img
            src="https://image.hanssem.com/hsimg/upload/homeIdea/2025/10/15/1760508599558_057278.jpg?w=1500"
            alt="Interior Design"
            style={{
              width: "100%",
              height: "500px",
              objectFit: "cover",
              display: "block",
            }}
          />
        </motion.div>
      </motion.div>

      {/* Features Section */}
      <motion.div
        style={{
          background: "#fff",
          padding: "80px 60px",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <h2
          style={{
            fontSize: "32px",
            fontWeight: "700",
            color: "#212529",
            textAlign: "center",
            marginBottom: "60px",
          }}
        >
          디자이너를 위한 혁신적인 기능
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: "40px",
            maxWidth: "1200px",
            margin: "0 auto",
          }}
        >
          {[
            {
              icon: <Lightbulb size={40} strokeWidth={1.5} />,
              title: "AI 자동 생성",
              description: "최첨단 AI 기술로 당신만의\n맞춤형 인테리어를 즉시 생성합니다",
              color: "#ff6b35",
            },
            {
              icon: <Clock size={40} strokeWidth={1.5} />,
              title: "빠른 디자인",
              description: "몇 분 안에 다양한 스타일의\n인테리어 시안을 확인하세요",
              color: "#ff6b35",
            },
            {
              icon: <Package size={40} strokeWidth={1.5} />,
              title: "무한한 아이디어",
              description: "다양한 컨셉과 스타일로\n당신의 공간을 완벽하게 연출합니다",
              color: "#ff6b35",
            },
          ].map((feature, index) => (
            <motion.div
              key={index}
              style={{
                background: "#fff",
                padding: "40px 32px",
                borderRadius: "12px",
                border: "1px solid #e9ecef",
                textAlign: "center",
                cursor: "pointer",
                transition: "all 0.3s ease",
              }}
              variants={fadeUp}
              whileHover={{
                y: -8,
                boxShadow: "0 12px 40px rgba(0, 0, 0, 0.08)",
              }}
            >
              <div
                style={{
                  width: "80px",
                  height: "80px",
                  margin: "0 auto 24px",
                  borderRadius: "12px",
                  background: "#fff5f2",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: feature.color,
                }}
              >
                {feature.icon}
              </div>

              <h3
                style={{
                  fontSize: "20px",
                  fontWeight: "600",
                  color: "#212529",
                  marginBottom: "12px",
                }}
              >
                {feature.title}
              </h3>

              <p
                style={{
                  fontSize: "15px",
                  color: "#6c757d",
                  lineHeight: "1.6",
                  margin: 0,
                  whiteSpace: "pre-line",
                }}
              >
                {feature.description}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.div>

      {/* Stats Section */}
      <motion.div
        style={{
          padding: "80px 60px",
          maxWidth: "1400px",
          margin: "0 auto",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: "40px",
            background: "#fff",
            padding: "60px 40px",
            borderRadius: "12px",
            border: "1px solid #e9ecef",
          }}
        >
          {[
            { value: "10,000+", label: "완성된 프로젝트" },
            { value: "5,000+", label: "만족한 사용자" },
            { value: "50+", label: "디자인 스타일" },
            { value: "99%", label: "고객 만족도" },
          ].map((stat, index) => (
            <motion.div
              key={index}
              style={{ textAlign: "center" }}
              variants={fadeUp}
            >
              <h2
                style={{
                  fontSize: "48px",
                  fontWeight: "700",
                  color: "#ff6b35",
                  marginBottom: "8px",
                }}
              >
                {stat.value}
              </h2>
              <p
                style={{
                  fontSize: "15px",
                  color: "#6c757d",
                  margin: 0,
                }}
              >
                {stat.label}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </main>
  );
}

export default Hero;
